package bassamalim.rune.core.crypto

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

class RuneTest {

    private fun ByteArray.hex() = joinToString("") { "%02x".format(it) }

    /** The contract with the desktop app: the same file, generated by the Rust core. */
    @Test
    fun `matches the shared vectors`() {
        val vectors = Json.parseToJsonElement(
            javaClass.getResource("/vectors.json")!!.readText()
        ).jsonArray
        assertTrue(vectors.isNotEmpty())

        for (vector in vectors) {
            val v = vector.jsonObject
            fun text(name: String) = v.getValue(name).jsonPrimitive.content
            fun number(name: String) = v.getValue(name).jsonPrimitive.int

            val master = Rune.masterKey(text("masterPassword"))
            val site = Rune.siteKey(master, text("site"), text("login"), number("counter"))

            assertEquals(text("masterKey"), master.hex())
            assertEquals(text("fingerprint"), Rune.fingerprint(master))
            assertEquals(text("siteKey"), site.hex())
            assertEquals(text("password"), Rune.password(site, number("length"), text("classes"), text("symbols")))
        }
    }

    @Test
    fun `refuses a bad policy`() {
        val key = ByteArray(32)
        val d = Rune.DEFAULT_SYMBOLS
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 3, "luds", d) }
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 65, "luds", d) }
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 20, "", d) }
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 20, "lx", d) }
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 20, "luds", "") }
        assertThrows(IllegalArgumentException::class.java) { Rune.password(key, 20, "luds", "é") }
        // Symbols off: the set doesn't matter.
        assertEquals(20, Rune.password(key, 20, "lud", "").length)
        assertEquals("!-.~", Rune.canonicalSymbols("~.-!!"))
    }

    @Test
    fun `a passphrase is six words picked uniformly from the list`() {
        // The same file the app ships, as Gradle runs unit tests from the module directory.
        val words = java.io.File("src/main/res/raw/words.txt").readLines()
        assertEquals(7776, words.size)
        // 65535 and 62208 fall in the rejected tail (62208 = 8 × 7776), so they pick nothing.
        val values = ArrayDeque(listOf(65535, 62208, 0, 1, 7776, 7777, 100, 62207))
        val phrase = Rune.passphrase(words) { values.removeFirst() }

        assertEquals(
            listOf(words[0], words[1], words[0], words[1], words[100], words[62207 % 7776]),
            phrase.split(" ")
        )
        assertEquals(78.0, Math.round(Rune.passphraseBits(words.size)).toDouble(), 0.0)
    }

    @Test
    fun `estimates strength`() {
        assertEquals(125.0, Math.round(Rune.entropyBits(20, "luds", Rune.DEFAULT_SYMBOLS)).toDouble(), 0.0)
        assertEquals(0.0, Rune.entropyBits(20, "", Rune.DEFAULT_SYMBOLS), 0.0)
    }
}
